const D = { energy: .6, density: .5, hue: 74, speed: 1, scale: 1, x: .5, y: .5, wobble: .5, act: 'cycle', style: 'specimen', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 read as grey indistinct mush. The growth sim was fine — the
// problem was pure VALUE COLLISION: thalli at b=42..74 on rock at b=46, and
// saturation stuck at s=16..56. Subject and substrate at the same brightness
// is mush no matter how good the model underneath is. The rock is now dark
// granite (b=32) and the four species carry real lichen colour — sulphur-
// yellow, rust-orange, sage, near-black slate. The contact seams between
// colonies are the image, so each thallus now draws BOTH a raised lit margin
// and a dark contact seam.
const MAXC = 26, NR = 44, TAU = Math.PI * 2;
const TW = Math.max(300, Math.min(900, Math.round(width * .5))), TH = Math.max(180, Math.round(TW * height / width));
const AW = 128, AH = Math.max(48, Math.round(AW * height / width));
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const hsh2 = (x, y) => { const s = Math.sin(x * 127.1 + y * 311.7 + P.seed * 74.7) * 43758.5453; return s - Math.floor(s); };
const vn = (x, y) => {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hsh2(xi, yi), b = hsh2(xi + 1, yi), c = hsh2(xi, yi + 1), d = hsh2(xi + 1, yi + 1);
  return (a * (1 - u) + b * u) * (1 - v) + (c * (1 - u) + d * u) * v;
};
const st = P.style;

if (!S.rk || S.tw !== TW || S.styleUsed !== st || S.seedUsed !== P.seed) {
  if (S.rk && S.rk.remove) S.rk.remove();
  if (S.ar && S.ar.remove) S.ar.remove();
  S.rk = createGraphics(TW, TH); S.rk.pixelDensity(1);
  S.ar = createGraphics(AW, AH); S.ar.pixelDensity(1);
  S.tw = TW; S.styleUsed = st; S.seedUsed = P.seed; S.tick = 0;
  // ---- substrate ----------------------------------------------------------
  const g = S.rk; g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  const rH = st === 'nocturne' ? 250 : st === 'plate' ? 38 : st === 'map' ? 44 : 24;
  const rS = st === 'nocturne' ? 30 : st === 'plate' ? 12 : st === 'map' ? 8 : 10;
  const rB = st === 'nocturne' ? 9 : st === 'plate' ? 64 : st === 'map' ? 72 : 32;
  g.background(rH, rS, rB);
  if (st !== 'map') {
    for (let i = 0; i < 900; i++) {         // rock mottle / paper tooth
      const dv = (fr(i * 4 + 1) - .5) * (st === 'plate' ? 8 : 26);
      g.fill(rH + (fr(i * 4 + 2) - .5) * 22, rS, Math.max(2, Math.min(97, rB + dv)), 20);
      const sz = (4 + fr(i * 4 + 3) * (st === 'plate' ? 12 : 90)) * (TW / 700);
      g.ellipse(fr(i * 4 + 4) * TW, fr(i * 6 + 1) * TH, sz, sz * (.6 + fr(i * 6 + 2) * .8));
    }
    if (st === 'specimen' || st === 'nocturne') {
      for (let i = 0; i < 340; i++) {        // mica flecks
        g.fill(rH + 20, rS * .4, Math.min(98, rB + 34 + fr(i * 3 + 1) * 30), 40);
        g.ellipse(fr(i * 3 + 2) * TW, fr(i * 3 + 3) * TH, 1.6 * (TW / 700), 1.6 * (TW / 700));
      }
      g.stroke(rH, rS, Math.max(2, rB - 22), 40); g.strokeWeight(TW / 700);
      for (let i = 0; i < 11; i++) {         // fractures
        let x = fr(i * 5 + 1) * TW, y = fr(i * 5 + 2) * TH, a = fr(i * 5 + 3) * 6.283;
        for (let s2 = 0; s2 < 22; s2++) { const nx2 = x + Math.cos(a) * TW * .035, ny2 = y + Math.sin(a) * TW * .035; g.line(x, y, nx2, ny2); x = nx2; y = ny2; a += (fr(i * 40 + s2) - .5) * .7; }
      }
      g.noStroke();
    }
  }
  // ---- areolate crackle overlay -------------------------------------------
  const a2 = S.ar; a2.loadPixels(); const ap = a2.pixels;
  for (let y = 0; y < AH; y++) for (let x = 0; x < AW; x++) {
    const n1 = vn(x * .16, y * .16), n2 = vn(x * .38 + 30, y * .38 + 30);
    const cr2 = Math.abs(n1 - .5) + Math.abs(n2 - .5) * .5;
    const v = 255 - Math.max(0, (.22 - cr2) * 5) * 150;
    const o = 4 * (y * AW + x); ap[o] = v; ap[o + 1] = v * .995; ap[o + 2] = v * .985; ap[o + 3] = 255;
  }
  a2.updatePixels();
  S.r = new Float32Array(MAXC * NR); S.wob = new Float32Array(MAXC * NR);
  S.ccx = new Float32Array(MAXC); S.ccy = new Float32Array(MAXC); S.age = new Float32Array(MAXC);
  S.life = new Float32Array(MAXC); S.cin = new Float32Array(MAXC); S.mx = new Float32Array(MAXC);
  S.sp = new Uint8Array(MAXC); S.cal = new Uint8Array(MAXC);
  S.ring = new Float32Array(MAXC * 4); S.nring = new Uint8Array(MAXC);
}

const rk = S.rk, ar = S.ar, R = S.r, wob = S.wob, ccx = S.ccx, ccy = S.ccy;
const age = S.age, life = S.life, cin = S.cin, mx = S.mx, sp = S.sp, cal = S.cal, ring = S.ring, nring = S.nring;
S.tick = (S.tick || 0) + 1;
const rnd = k => { const s = Math.sin(k * 12.9898 + S.tick * .6180339 + P.seed * 7.13) * 43758.5453; return s - Math.floor(s); };
const u = Math.min(width, height);
const RMAX = u * (.09 + P.scale * .13);

// ---- moisture: lichens swell and saturate when wet (the motion floor) -----
let clim;
if (P.act === 'flush') clim = 1.7;
else if (P.act === 'desiccate') clim = .38;
else clim = .45 + 1.3 * (.5 + .5 * Math.sin(K.t * .0113 + .8 * Math.sin(K.t * .0037 + .9)));
const wet = (.5 + .5 * Math.sin(K.t * .061 + .7 * Math.sin(K.t * .0233 + 1.4))) * (.35 + .65 * clim);
const swell = 1 + wet * (.02 + P.energy * .05);

// ---- radius lookup on another colony (for contact inhibition) -------------
const radAt = (m, angle) => {
  let j = Math.round(((angle % TAU) + TAU) % TAU / TAU * NR) % NR;
  return R[m * NR + j] * wob[m * NR + j];
};

// ---- grow ------------------------------------------------------------------
const aging = (.35 + P.speed * .85) * (.5 + P.energy * .9);
const gRate = u * .00028 * (.3 + P.energy * 1.5) * (.4 + P.speed * .9);
let nAlive = 0;
for (let k = 0; k < MAXC; k++) {
  if (!cal[k]) continue;
  nAlive++;
  age[k] += aging;
  if (nring[k] < 4 && age[k] > (nring[k] + 1) * 620) { ring[k * 4 + nring[k]] = mx[k] * .96; nring[k]++; }
  if (age[k] > life[k]) cin[k] += u * .00012 * (.4 + P.speed * .9) * (.4 + P.energy * 1.1);
  let m2 = 0;
  const slow = Math.max(.08, 1 - age[k] / (life[k] * 1.7));
  for (let j = 0; j < NR; j++) {
    const idx = k * NR + j, a = j / NR * TAU;
    const r0 = R[idx];
    const tipx = ccx[k] + Math.cos(a) * (r0 + gRate * 2.5) * wob[idx];
    const tipy = ccy[k] + Math.sin(a) * (r0 + gRate * 2.5) * wob[idx];
    let blocked = r0 > RMAX;
    if (!blocked) for (let o = 0; o < MAXC; o++) {
      if (o === k || !cal[o]) continue;
      const dx = tipx - ccx[o], dy = tipy - ccy[o], d2 = dx * dx + dy * dy;
      if (d2 > mx[o] * mx[o]) continue;                       // cheap circle reject
      if (Math.sqrt(d2) < radAt(o, Math.atan2(dy, dx))) { blocked = true; break; }
    }
    if (!blocked) R[idx] = r0 + gRate * slow * (.35 + wet * .9);
    if (R[idx] > m2) m2 = R[idx];
  }
  mx[k] = m2 * 1.06;
  if (cin[k] > m2) cal[k] = 0;
}

// ---- propagules land in freed rock -----------------------------------------
const want = 6 + Math.round(P.density * 16);
if (nAlive < want) {
  for (let k = 0; k < MAXC; k++) if (!cal[k]) {
    let bx = width * .5, by = height * .5, best = -1e9, clear = -1e9;
    for (let q = 0; q < 10; q++) {
      const px2 = rnd(k * 17 + q * 3 + 1) * width, py2 = rnd(k * 17 + q * 3 + 2) * height;
      let mn = 1e9;
      for (let o = 0; o < MAXC; o++) if (cal[o]) mn = Math.min(mn, Math.hypot(px2 - ccx[o], py2 - ccy[o]) - mx[o]);
      // propagules settle preferentially around the anchor
      const sc = mn - Math.hypot(px2 / width - P.x, py2 / height - P.y) * u * .5;
      if (sc > best) { best = sc; clear = mn; bx = px2; by = py2; }
    }
    if (clear < -RMAX * .3) break;
    cal[k] = 1; ccx[k] = bx; ccy[k] = by; age[k] = 0; cin[k] = 0; nring[k] = 0;
    life[k] = 2400 + rnd(k * 23 + 5) * 3000; sp[k] = Math.floor(rnd(k * 29 + 7) * 4) % 4; mx[k] = u * .006;
    for (let j = 0; j < NR; j++) {
      R[k * NR + j] = u * .004;
      wob[k * NR + j] = 1 + (vn(Math.cos(j / NR * TAU) * 2.4 + k * 9.1, Math.sin(j / NR * TAU) * 2.4 + k * 4.7) - .5) * (.14 + P.wobble * .5);
    }
    break;
  }
}

// ---- render ----------------------------------------------------------------
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(rk, 0, 0, width, height);
pop();

// four crustose species, as offsets from P.hue so `hue` still steers the whole
// mosaic: sulphur-yellow map lichen, rust-orange Caloplaca, sage Lecanora,
// near-black Verrucaria. These are the colours lichens actually are.
const spH = [-8, -48, 22, 136], spS = [.86, .92, .30, .34], spB = [.92, .90, .70, .22];
const rockB = st === 'nocturne' ? 9 : st === 'plate' ? 64 : st === 'map' ? 72 : 32;
const rockH = st === 'nocturne' ? 250 : st === 'plate' ? 38 : st === 'map' ? 44 : 24;
push();
if (st === 'nocturne') { drawingContext.shadowBlur = u * .022; }
for (let k = 0; k < MAXC; k++) {
  if (!cal[k]) continue;
  const spk = sp[k];
  const hh = P.hue + spH[spk];
  let ss, bb;
  if (st === 'map') { ss = 78 * spS[spk] + 22; bb = 82 * spB[spk] + 12; }
  else if (st === 'plate') { ss = (22 + wet * 10) * (.5 + spS[spk] * .6); bb = 30 + spB[spk] * 26 - wet * 6; }
  else if (st === 'nocturne') { ss = (74 + wet * 20) * (.5 + spS[spk] * .6); bb = (52 + wet * 40 + P.energy * 14) * (.4 + spB[spk] * .7); }
  else { const base = 58 + wet * 26 + P.energy * 12; ss = base * spS[spk]; bb = (62 + wet * 20 + P.energy * 10) * spB[spk]; }
  if (st === 'nocturne') drawingContext.shadowColor = color(hh, ss, bb, 60);
  // thallus
  noStroke(); fill(hh, Math.min(100, ss), Math.min(100, bb), st === 'plate' ? 44 : 92);
  beginShape();
  for (let j = 0; j < NR; j++) { const a = j / NR * TAU, r2 = R[k * NR + j] * wob[k * NR + j] * swell; vertex(ccx[k] + Math.cos(a) * r2, ccy[k] + Math.sin(a) * r2); }
  endShape(CLOSE);
  drawingContext.shadowBlur = st === 'nocturne' ? u * .022 : 0;
  // zonation rings — laid down at past growth stages, now overgrown
  noFill(); strokeWeight(Math.max(.8, u * .0012 * (.5 + P.density * 1.4)));
  for (let n = 0; n < nring[k]; n++) {
    stroke(hh, Math.min(100, ss * (st === 'map' ? .5 : 1.2)), Math.min(100, bb * (n % 2 ? 1.24 : .74)), st === 'map' ? 80 : 62);
    beginShape();
    for (let j = 0; j < NR; j++) {
      const a = j / NR * TAU, lim = R[k * NR + j] * .96, r2 = Math.min(ring[k * 4 + n], lim) * wob[k * NR + j] * swell;
      vertex(ccx[k] + Math.cos(a) * r2, ccy[k] + Math.sin(a) * r2);
    }
    endShape(CLOSE);
  }
  // the raised margin: a lit rim just inside the edge. A crustose thallus grows
  // from its margin, so this is the live tissue and it catches the light.
  strokeWeight(Math.max(1.2, u * .0026 * (.5 + P.density * 1.3)));
  stroke(hh + 4, Math.min(100, ss * .55), Math.min(100, bb * 1.55 + 20), st === 'plate' ? 92 : 90);
  beginShape();
  for (let j = 0; j < NR; j++) { const a = j / NR * TAU, r2 = R[k * NR + j] * wob[k * NR + j] * swell * .955; vertex(ccx[k] + Math.cos(a) * r2, ccy[k] + Math.sin(a) * r2); }
  endShape(CLOSE);
  // the contact seam: where two colonies meet they stop dead, and the hard black
  // line between them is the whole point of the image
  strokeWeight(Math.max(1, u * .0016 * (.5 + P.density * 1.2)));
  stroke(hh, Math.min(100, ss * .6), st === 'nocturne' ? Math.min(100, bb + 30) : Math.max(3, bb * .16), 94);
  beginShape();
  for (let j = 0; j < NR; j++) { const a = j / NR * TAU, r2 = R[k * NR + j] * wob[k * NR + j] * swell; vertex(ccx[k] + Math.cos(a) * r2, ccy[k] + Math.sin(a) * r2); }
  endShape(CLOSE);
  if (st === 'plate') {   // engraved radial hatching
    strokeWeight(Math.max(.6, u * .0009));
    stroke(hh, ss + 14, Math.max(6, bb * .5), 46);
    for (let j = 0; j < NR; j += 3) {
      const a = j / NR * TAU, r2 = R[k * NR + j] * wob[k * NR + j] * swell;
      line(ccx[k] + Math.cos(a) * r2 * .32, ccy[k] + Math.sin(a) * r2 * .32, ccx[k] + Math.cos(a) * r2 * .93, ccy[k] + Math.sin(a) * r2 * .93);
    }
  }
  // necrotic centre — the rock shows through again
  if (cin[k] > 0) {
    noStroke(); fill(rockH, st === 'map' ? 6 : 10, rockB, 96);
    beginShape();
    for (let j = 0; j < NR; j++) { const a = j / NR * TAU, r2 = Math.min(cin[k], R[k * NR + j] * .97) * wob[k * NR + j]; vertex(ccx[k] + Math.cos(a) * r2, ccy[k] + Math.sin(a) * r2); }
    endShape(CLOSE);
  }
}
drawingContext.shadowBlur = 0;
pop();

// ---- areolate texture over everything --------------------------------------
push();
blendMode(MULTIPLY);
tint(0, 0, 100, Math.min(100, (28 + P.density * 62) * (P.alpha / 100)));
image(ar, 0, 0, width, height);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
